public async run<T>(jobName, config, soloRun, allowParallelRun): Promise<void> {
  if ((allowParallelRun === false && this.JobRunning === true) || this.JobNoParallelRunning === true) { throw new Error('Can\'t start this job while another is running'); }
  const t = this.findJob(jobName);
  if (t) { t.JobListener = this; await t.start(config, soloRun, allowParallelRun); }

public stop(jobName: string): void {
  const t = this.findJob(jobName);
  if (t) { t.cancel(); } else { Logger.warn(LOG_TAG, 'cannot find job to stop:' + jobName); }
}

